import gurobipy as gp
from gurobipy import GRB
I = list(range(1, 111))
c = {1: 50, 2: 40, 3: 30, 4: 25, 5: 20, 6: 65, 7: 80, 8: 15, 9: 48, 10: 55, 11: 87, 12: 82, 13: 123, 14: 137, 15: 43, 16: 110, 17: 94, 18: 101, 19: 54, 20: 143, 21: 37, 22: 46, 23: 81, 24: 100, 25: 80, 26: 102, 27: 109, 28: 79, 29: 100, 30: 119, 31: 139, 32: 11, 33: 144, 34: 56, 35: 59, 36: 73, 37: 136, 38: 85, 39: 111, 40: 103, 41: 146, 42: 82, 43: 144, 44: 143, 45: 85, 46: 121, 47: 147, 48: 92, 49: 115, 50: 13, 51: 145, 52: 48, 53: 74, 54: 135, 55: 28, 56: 74, 57: 89, 58: 24, 59: 141, 60: 27, 61: 106, 62: 37, 63: 114, 64: 11, 65: 113, 66: 61, 67: 62, 68: 145, 69: 148, 70: 30, 71: 134, 72: 97, 73: 103, 74: 102, 75: 141, 76: 109, 77: 118, 78: 93, 79: 95, 80: 92, 81: 71, 82: 127, 83: 126, 84: 123, 85: 137, 86: 124, 87: 103, 88: 119, 89: 87, 90: 87, 91: 92, 92: 69, 93: 149, 94: 146, 95: 47, 96: 12, 97: 101, 98: 69, 99: 46, 100: 79, 101: 93, 102: 49, 103: 110, 104: 133, 105: 92, 106: 106, 107: 144, 108: 124, 109: 148, 110: 127}
v = {1: 60, 2: 50, 3: 45, 4: 35, 5: 28, 6: 75, 7: 100, 8: 20, 9: 62, 10: 70, 11: 117, 12: 109, 13: 172, 14: 180, 15: 62, 16: 147, 17: 141, 18: 151, 19: 75, 20: 185, 21: 51, 22: 59, 23: 105, 24: 123, 25: 104, 26: 153, 27: 163, 28: 114, 29: 125, 30: 160, 31: 166, 32: 15, 33: 184, 34: 86, 35: 85, 36: 109, 37: 187, 38: 115, 39: 155, 40: 137, 41: 204, 42: 98, 43: 189, 44: 178, 45: 130, 46: 148, 47: 205, 48: 128, 49: 165, 50: 18, 51: 203, 52: 72, 53: 92, 54: 167, 55: 40, 56: 89, 57: 111, 58: 38, 59: 190, 60: 33, 61: 148, 62: 44, 63: 167, 64: 14, 65: 153, 66: 91, 67: 94, 68: 188, 69: 177, 70: 36, 71: 179, 72: 143, 73: 123, 74: 126, 75: 173, 76: 152, 77: 170, 78: 148, 79: 142, 80: 118, 81: 104, 82: 159, 83: 163, 84: 165, 85: 164, 86: 149, 87: 144, 88: 166, 89: 105, 90: 130, 91: 138, 92: 96, 93: 178, 94: 193, 95: 68, 96: 18, 97: 131, 98: 103, 99: 65, 100: 108, 101: 130, 102: 60, 103: 157, 104: 184, 105: 130, 106: 128, 107: 201, 108: 173, 109: 189, 110: 177}
if set(c.keys()) != set(I) or set(v.keys()) != set(I):
    raise ValueError('Project data missing for some indices.')
m = gp.Model('ProjectSelection')
x = m.addVars(I, vtype=GRB.BINARY, name='')
m.setObjective(gp.quicksum((v[i] * x[i] for i in I)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((c[i] * x[i] for i in I)) <= 1000, name='budget')
m.addConstr(x[4] + x[7] <= 1, name='mutual_4_7')
m.addConstr(x[6] <= x[1], name='prereq_6_1')
m.addConstr(x[10] <= x[5], name='contingent_10_5')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for i in I:
        print(f'x[{i}]: {x[i].X}')
else:
    print(f'Solver status: {m.Status}')